pragma solidity >=0.8.0;

contract CryptoHashWidthProbe {
    bytes32 public k16;
    bytes32 public e16;
    bytes32 public k32;
    bytes32 public e32;
    bytes32 public k64;
    bytes32 public e64;

    function set(uint16 a, uint32 b, uint64 c) public {
        k16 = keccak256(abi.encodePacked(a));
        e16 = keccak256(abi.encode(a));
        k32 = keccak256(abi.encodePacked(b));
        e32 = keccak256(abi.encode(b));
        k64 = keccak256(abi.encodePacked(c));
        e64 = keccak256(abi.encode(c));
    }

    function getK16() public view returns (bytes32) { return k16; }
    function getE16() public view returns (bytes32) { return e16; }
    function getK32() public view returns (bytes32) { return k32; }
    function getE32() public view returns (bytes32) { return e32; }
    function getK64() public view returns (bytes32) { return k64; }
    function getE64() public view returns (bytes32) { return e64; }
}
